// ---- Per-episode shot editor (the detailed "AI phân cảnh" screen) ----

export type SegmentLineTag = "subtitle_config" | "bgm" | "dialogue" | "visual";

export type SegmentLine = {
  id: string;
  durationSec: number;
  tag: SegmentLineTag;
  character?: string;
  direction?: string; // parenthetical emotion/action note
  shotType?: string; // for visual lines: Toàn cảnh, Trung cảnh, Cận cảnh, Đặc tả...
  text: string;
};

export type Segment = {
  id: number;
  title: string; // "Đoạn 1"
  durationSec: number;
  status: "pending" | "generating" | "done" | "failed";
  lines: SegmentLine[];
};

const line = (
  id: string,
  durationSec: number,
  tag: SegmentLineTag,
  text: string,
  extra: Partial<SegmentLine> = {}
): SegmentLine => ({ id, durationSec, tag, text, ...extra });

