const genericSegments = (episodeId: number): Segment[] =>
  Array.from({ length: 4 }, (_, i) => {
    const n = i + 1;
    return {
      id: n,
      title: `Đoạn ${n}`,
      durationSec: 12 + n * 2,
      status: "pending" as const,
      lines: [
        line(`${episodeId}-${n}-bgm`, 0, "bgm", "Nhạc nền: theo tông màu chung của dự án, âm lượng thấp hơn lời thoại"),
        line(`${episodeId}-${n}-v1`, 6, "visual", "Cảnh quay minh hoạ diễn biến chính của đoạn này, tham chiếu tài sản nhân vật/bối cảnh đã tạo.", {
          shotType: n % 2 === 0 ? "Trung cảnh" : "Toàn cảnh",
        }),
        line(`${episodeId}-${n}-d1`, 4, "dialogue", "(Lời thoại minh hoạ — chỉnh sửa trực tiếp trong khung nội dung của đoạn.)", {
          character: "Nhân vật",
          direction: "chưa xác định cảm xúc",
        }),
      ],
    };
  });

export function getSegmentsForEpisode(episodeId: number): Segment[] {
  if (episodeId === 1) return episode1Segments;
  return genericSegments(episodeId);
}

